const fs = require('fs');
let code = fs.readFileSync('src/components/ChatView.tsx', 'utf8');

const oldTypingSoundEffect = `  // Typing sound effect
  const typingSound = useRef(new Audio("data:audio/mp3;base64,"));
  useEffect(() => {
    typingSound.current.loop = true;
    if (typingUsers.length > 0) {
      typingSound.current.play().catch(() => {});
    } else {
      typingSound.current.pause();
      typingSound.current.currentTime = 0;
    }
  }, [typingUsers.length]);`;

const newTypingSoundEffect = `  // Typing sound effect
  const typingAudioRef = useRef<HTMLAudioElement | null>(null);
  
  useEffect(() => {
    // Only instantiate Audio once to avoid memory leaks
    if (!typingAudioRef.current) {
      const audio = new Audio("data:audio/mp3;base64,");
      audio.preload = "auto";
      audio.loop = true;
      typingAudioRef.current = audio;
    }

    // Try unlocking audio context on first user interaction if needed
    const unlockAudio = () => {
      // Just resolving the interaction requirement
      document.removeEventListener('click', unlockAudio);
      document.removeEventListener('keydown', unlockAudio);
      document.removeEventListener('touchstart', unlockAudio);
    };
    
    document.addEventListener('click', unlockAudio);
    document.addEventListener('keydown', unlockAudio);
    document.addEventListener('touchstart', unlockAudio);

    return () => {
      document.removeEventListener('click', unlockAudio);
      document.removeEventListener('keydown', unlockAudio);
      document.removeEventListener('touchstart', unlockAudio);
    };
  }, []);

  useEffect(() => {
    if (typingUsers.length > 0) {
      if (typingAudioRef.current) {
        typingAudioRef.current.play().catch(e => console.error("Typing audio play error:", e));
      }
    } else {
      if (typingAudioRef.current) {
        typingAudioRef.current.pause();
        typingAudioRef.current.currentTime = 0;
      }
    }
  }, [typingUsers.length]);`;

code = code.replace(oldTypingSoundEffect, newTypingSoundEffect);

fs.writeFileSync('src/components/ChatView.tsx', code);
console.log('Fixed typing sound');
